 using S=NativeDisplaySignedNumber;using M=NativeDisplayMarker;using G=NativeDisplayDifferenceGlyph;using D=NativeDisplayParameterDifference;using B=NativeDisplayBarGraph;using P=NativeDisplayParameter;using F=NativeDisplayValueFormat;using X=NativeDisplayTableText;using J=std::variant<std::monostate,S,M,G,D,B,P,F,X>;
public:enum class External:uint8_t{None,Numeric,Lcd,Lookup};struct CodeRange{uint32_t begin,end;};inline static constexpr std::array<CodeRange,4>CodeRanges{{{0x132c,0x1374},{0x23f8,0x24b8},{0x4454,0x449e},{0x4618,0x481a}}};static bool candidate(uint32_t pc){for(auto r:CodeRanges)if(pc>=r.begin&&pc<r.end)return true;return false;}void reset(){for(auto&j:jobs_)j.emplace<std::monostate>();depth_=0;}bool active()const{return depth_!=0;}bool admit(Stage1Cpu&c,uint32_t verifiedReturn){if(depth_||midi_projection::blocked(c))return false;auto pc=uint32_t(c.getPC());if(pc==0x132c)jobs_[depth_++].emplace<S>(uint8_t(c.reg8(8)));else if(pc==0x23f8)jobs_[depth_++].emplace<B>(uint8_t(c.reg8(14)),verifiedReturn);else if(pc==0x2438)jobs_[depth_++].emplace<G>(uint16_t(c.reg16(6)));else if(pc==0x248a||pc==0x2492)jobs_[depth_++].emplace<M>(pc==0x248a?DisplayMarkerTask::Kind::Set:DisplayMarkerTask::Kind::Show,uint8_t(c.reg8(14)),verifiedReturn);else if(pc==0x4454)jobs_[depth_++].emplace<D>(uint32_t(c.reg32(1)));else if(pc==0x4618)jobs_[depth_++].emplace<P>(uint8_t(c.reg8(9)));else if(pc==0x4644)jobs_[depth_++].emplace<F>(uint8_t(c.reg8(9)),uint8_t(c.reg8(8)),verifiedReturn);else return false;return true;}
 External external()const{if(!depth_)return External::None;auto&j=jobs_[depth_-1];if(auto*p=std::get_if<S>(&j);p&&p->task().awaitingChild())return External::Numeric;if(auto*p=std::get_if<M>(&j);p&&p->task().awaitingChild())return External::Lcd;if(auto*p=std::get_if<G>(&j);p&&p->task().awaitingChild())return External::Lcd;if(auto*p=std::get_if<B>(&j);p&&p->task().awaitingChild())return External::Lcd;if(auto*p=std::get_if<D>(&j);p&&p->task().awaitingChild()&&p->task().child()==DisplayParameterDifferenceTask::Child::Lookup)return External::Lookup;if(auto*p=std::get_if<F>(&j);p&&p->task().awaitingChild()){auto ch=p->task().child();return ch==DisplayValueFormatTask::Child::Number?External::Numeric:ch==DisplayValueFormatTask::Child::Off?External::Lcd:External::None;}if(auto*p=std::get_if<X>(&j);p&&p->task().awaitingChild()&&p->task().child()!=DisplayTableTextTask::Child::Marker)return External::Lcd;return External::None;}
 bool step(Stage1Cpu&c){if(midi_projection::blocked(c))return false;for(unsigned i=0;i<8;++i){if(!depth_)return false;auto&j=jobs_[depth_-1];if(auto*p=std::get_if<F>(&j);p&&p->task().stage()==DisplayValueFormatTask::Stage::TableText){if(depth_==jobs_.size()||!p->startTable())return false;jobs_[depth_++].emplace<X>(uint32_t(c.reg32(1)),uint8_t(c.reg8(8)));continue;}bool waiting=std::visit([](const auto&v){using V=std::decay_t<decltype(v)>;if constexpr(std::is_same_v<V,std::monostate>)return false;else return v.task().awaitingChild();},j);if(waiting){bool resumed=std::visit([&](auto&v){using V=std::decay_t<decltype(v)>;if constexpr(std::is_same_v<V,std::monostate>)return false;else return v.resumeChild(c);},j);if(resumed){bool done=std::visit([](const auto&v){using V=std::decay_t<decltype(v)>;if constexpr(std::is_same_v<V,std::monostate>)return true;else return v.task().complete();},j);if(done){j.emplace<std::monostate>();--depth_;}continue;}if(auto*p=std::get_if<P>(&j);p&&depth_<jobs_.size()){auto ch=p->task().child();if(ch==DisplayParameterTask::Child::Format&&uint32_t(c.getPC())==0x4644)jobs_[depth_++].emplace<F>(uint8_t(c.reg8(9)),uint8_t(c.reg8(8)),0x4636);else if(ch==DisplayParameterTask::Child::Difference&&uint32_t(c.getPC())==0x4454)jobs_[depth_++].emplace<D>(uint32_t(c.reg32(1)));else if(ch==DisplayParameterTask::Child::Marker&&uint32_t(c.getPC())==0x2492)jobs_[depth_++].emplace<M>(DisplayMarkerTask::Kind::Show,uint8_t(c.reg8(14)),0x4642);else return false;continue;}if(auto*p=std::get_if<F>(&j);p&&depth_<jobs_.size()){auto ch=p->task().child();if(ch==DisplayValueFormatTask::Child::Marker&&uint32_t(c.getPC())==0x248a)jobs_[depth_++].emplace<M>(DisplayMarkerTask::Kind::Set,uint8_t(c.reg8(14)),0x464a);else if(ch==DisplayValueFormatTask::Child::Signed&&uint32_t(c.getPC())==0x132c)jobs_[depth_++].emplace<S>(uint8_t(c.reg8(8)));else return false;continue;}if(auto*p=std::get_if<X>(&j);p&&p->task().child()==DisplayTableTextTask::Child::Marker&&uint32_t(c.getPC())==0x248a&&depth_<jobs_.size()){jobs_[depth_++].emplace<M>(DisplayMarkerTask::Kind::Set,uint8_t(c.reg8(14)),0x46b0);continue;}if(auto*p=std::get_if<D>(&j);p&&p->task().child()==DisplayParameterDifferenceTask::Child::Glyph&&uint32_t(c.getPC())==0x2438&&depth_<jobs_.size()){jobs_[depth_++].emplace<G>(uint16_t(c.reg16(6)));continue;}return false;}bool ok=std::visit([&](auto&v){using V=std::decay_t<decltype(v)>;if constexpr(std::is_same_v<V,std::monostate>)return false;else return v.step(c);},j);if(!ok)return false;bool done=std::visit([](const auto&v){using V=std::decay_t<decltype(v)>;if constexpr(std::is_same_v<V,std::monostate>)return true;else return v.task().complete();},j);if(done){j.emplace<std::monostate>();--depth_;}return true;}return false;}
private:std::array<J,4>jobs_{};unsigned depth_=0;
